package com.learnagent.memory;

import com.fasterxml.jackson.databind.ObjectMapper;import io.github.openspacedrepetition.*;import java.time.*;import org.springframework.stereotype.Service;
@Service public class FsrsSchedulerService{public static final double DESIRED_RETENTION=.90;private final Scheduler scheduler;private final ObjectMapper json;public FsrsSchedulerService(ObjectMapper json){this.json=json;this.scheduler=Scheduler.builder().desiredRetention(DESIRED_RETENTION).learningSteps(new Duration[]{Duration.ofMinutes(1),Duration.ofMinutes(10)}).relearningSteps(new Duration[]{Duration.ofMinutes(10)}).maximumInterval(36500).enableFuzzing(false).build();}public InitialState initialize(java.util.UUID id,Instant now){Card card=Card.builder().cardId(Math.abs(id.hashCode())).due(now).build();return new InitialState(write(card),card.getDue(),card.getDifficulty(),card.getStability(),1.0);}public ScheduledState schedule(String stateJson,MemoryRating value,Instant now,int durationSeconds){Card before=read(stateJson);Rating rating=Rating.valueOf(value.name());CardAndReviewLog result=scheduler.reviewCard(before,rating,now,Math.max(0,durationSeconds)*1000);Card after=result.card();double retrieval=scheduler.getCardRetrievability(after,now);long seconds=Math.max(0,Duration.between(now,after.getDue()).getSeconds());int days=(int)Math.ceil(seconds/86400.0);return new ScheduledState(write(before),write(after),after.getDue(),after.getDifficulty(),after.getStability(),retrieval,days);}public double retrievability(String stateJson,Instant at){return scheduler.getCardRetrievability(read(stateJson),at);}public double desiredRetention(){return scheduler.getDesiredRetention();}private String write(Card card){try{return json.writeValueAsString(new CardState(card.getCardId(),card.getState().name(),card.getStep(),card.getStability(),card.getDifficulty(),card.getDue(),card.getLastReview()));}catch(Exception e){throw new IllegalStateException("Could not serialize FSRS card.",e);}}private Card read(String value){try{CardState state=json.readValue(value,CardState.class);return Card.builder().cardId(state.cardId()).state(State.valueOf(state.state())).step(state.step()).stability(state.stability()).difficulty(state.difficulty()).due(state.due()).lastReview(state.lastReview()).build();}catch(Exception e){throw new IllegalStateException("Stored FSRS state is invalid.",e);}}private record CardState(int cardId,String state,Integer step,Double stability,Double difficulty,Instant due,Instant lastReview){}public record InitialState(String cardJson,Instant due,Double difficulty,Double stability,double retrievability){}public record ScheduledState(String beforeJson,String afterJson,Instant due,Double difficulty,Double stability,double retrievability,int scheduledDays){} }
